// Synchronization Module on the node (thesis sections 3.7.4 and 3.13).
//
//  1. Detect network availability (the server must answer, not just Wi-Fi).
//  2. Identify unsynchronized local changes: pending Synchronization Records.
//  3. Package them: one change per record, with the last server version seen
//     (for conflict detection) and the fields changed.
//  4. Send them to the synchronization endpoint.
//  5. Retrieve changes generated by other nodes (everything after the last
//     server sequence number seen).
//  6-8. Version comparison, conflict detection and the conflict-resolution
//     rules run on the server; its answer says how each change was resolved.
//  9. Update the local database and regenerate affected schedules.
// 10. Mark the Synchronization Records as synced (or failed, with the reason).
// 11. Retry: if the server cannot be reached, sync is retried with increasing
//     delays (30 s, 1 min, 2 min, ... up to the configured maximum).
// Nothing is removed from the outbox until the server has confirmed it.

import { api, isServerReachable, AuthError, OfflineError } from './api.js';
import { db, SYNCED_TABLES, getMeta, setMeta, getNodeId } from './db.js';
import { getSession } from './auth.js';
import { getSettings, loadConfig, loadStoredSettings } from './config.js';
import { refreshSchedules, refreshIfNewDay } from './schedules.js';

const BATCH_SIZE = 100;
const FIRST_RETRY_MS = 30000;
const TABLE_ORDER = { guardians: 0, patients: 1, vaccination_records: 2 };

let state = { status: 'idle', lastSyncAt: null, error: null, nextRetryAt: null, failures: 0 };
const listeners = new Set();
let running = null;
let timer = null;
let debounce = null;

function setState(patch) {
  state = { ...state, ...patch };
  listeners.forEach((fn) => fn());
}

export const getSyncState = () => state;
export function subscribeSync(fn) {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

const stripLocal = (row) => Object.fromEntries(Object.entries(row).filter(([k]) => !k.startsWith('_')));

// Groups pending sync records into one change per record.
async function pendingChanges(nodeId) {
  const pending = await db.sync_records.where('sync_status').equals('pending').sortBy('timestamp');
  const groups = new Map();
  for (const s of pending) {
    const key = `${s.table_name}:${s.record_id}`;
    if (!groups.has(key)) groups.set(key, { table: s.table_name, id: s.record_id, syncRecords: [] });
    groups.get(key).syncRecords.push(s);
  }
  const ordered = [...groups.values()].sort((a, b) => TABLE_ORDER[a.table] - TABLE_ORDER[b.table]).slice(0, BATCH_SIZE);
  const changes = [];
  for (const group of ordered) {
    const row = await db[group.table].get(group.id);
    if (!row) continue;
    const last = group.syncRecords.at(-1);
    const isNew = (row.version ?? 0) === 0;
    changes.push({
      group,
      change: {
        // The id of the latest local change makes a retry of the same
        // change recognisable to the server.
        change_id: `${nodeId}:${last.id}`,
        table: group.table,
        change_type: isNew ? 'create' : last.change_type,
        base_version: row.version ?? 0,
        changed_fields: [...new Set(group.syncRecords.flatMap((s) => s.changed_fields))],
        record: stripLocal(row),
      },
    });
  }
  return changes;
}

async function pushData(nodeId) {
  for (let round = 0; round < 50; round++) {
    const batch = await pendingChanges(nodeId);
    if (!batch.length) return;
    const { results } = await api('/sync/push', { method: 'POST', body: { changes: batch.map((b) => b.change) } });

    const patientIds = new Set();
    await db.transaction('rw', [...SYNCED_TABLES.map((t) => db[t]), db.sync_records], async () => {
      for (let i = 0; i < batch.length; i++) {
        const { group } = batch[i];
        const result = results[i];
        const sentIds = group.syncRecords.map((s) => s.id);
        const rejected = result.status === 'rejected';
        await db.sync_records.where('id').anyOf(sentIds).modify({
          sync_status: rejected ? 'failed' : 'synced', conflict_status: result.conflict_status ?? 'none',
          error: result.error ?? null, version_number: result.record?.version ?? null, synced_at: new Date().toISOString(),
        });
        if (rejected) {
          await db[group.table].update(group.id, { _sync_error: result.error });
          continue;
        }
        const newerEdits = await db.sync_records.where('record_id').equals(group.id).filter((s) => s.sync_status === 'pending').count();
        if (newerEdits) {
          // Edited again while this push was in flight: keep the new edits and
          // send them against the version the server just accepted.
          await db[group.table].update(group.id, { version: result.record.version });
        } else {
          await db[group.table].put({ ...result.record, _sync_error: null });
        }
        patientIds.add(group.table === 'vaccination_records' ? result.record.patient_id : result.record.id);
      }
    });
    if (patientIds.size) await refreshSchedules([...patientIds]);
  }
}

async function pushAudit() {
  for (;;) {
    const rows = await db.audit_log.where('synced').equals(0).limit(BATCH_SIZE).toArray();
    if (!rows.length) return;
    const changes = rows.map(({ synced, ...record }) => ({
      change_id: `audit:${record.id}`, table: 'audit_log', change_type: 'create', base_version: 0, record,
    }));
    await api('/sync/push', { method: 'POST', body: { changes } });
    await db.audit_log.where('id').anyOf(rows.map((r) => r.id)).modify({ synced: 1 });
  }
}

async function pull() {
  let since = await getMeta('lastSeq', 0);
  for (;;) {
    const res = await api(`/sync/pull?since=${since}`);
    const patientIds = new Set();
    await db.transaction('rw', [...SYNCED_TABLES.map((t) => db[t]), db.sync_records, db.meta], async () => {
      for (const { table, record } of res.changes) {
        // Records edited locally since are kept; the server merges them on the next push.
        const pending = await db.sync_records.where('record_id').equals(record.id).filter((s) => s.sync_status === 'pending').count();
        if (pending) continue;
        await db[table].put(record);
        if (table === 'patients') patientIds.add(record.id);
        if (table === 'vaccination_records') patientIds.add(record.patient_id);
        if (table === 'guardians') (await db.patients.where('guardian_id').equals(record.id).primaryKeys()).forEach((id) => patientIds.add(id));
      }
      since = res.last_seq;
      await db.meta.put({ key: 'lastSeq', value: since });
    });
    if (patientIds.size) await refreshSchedules([...patientIds]);
    if (!res.more) return;
  }
}

async function runSync() {
  if (!getSession()) return;
  setState({ status: 'syncing', error: null });
  try {
    if (!(await isServerReachable())) throw new OfflineError('Server not reachable');
    const nodeId = await getNodeId();
    await pushData(nodeId);
    await pushAudit();
    await pull();
    if (await loadConfig()) await refreshSchedules();
    await refreshIfNewDay();
    const at = new Date().toISOString();
    await setMeta('lastSyncAt', at);
    setState({ status: 'idle', lastSyncAt: at, failures: 0, nextRetryAt: null });
  } catch (err) {
    const failures = state.failures + 1;
    if (err instanceof AuthError) setState({ status: 'auth', error: 'Log out and log in again while online to resume syncing.', failures });
    else if (err instanceof OfflineError) setState({ status: 'offline', failures });
    else setState({ status: 'error', error: err.message, failures });
  }
}

function retryDelay() {
  const max = getSettings().sync_max_retry_seconds * 1000;
  return Math.min(FIRST_RETRY_MS * 2 ** Math.max(state.failures - 1, 0), max);
}

async function tick() {
  clearTimeout(timer);
  if (!running) running = runSync().finally(() => { running = null; });
  await running;
  const delay = state.status === 'idle' ? getSettings().sync_interval_seconds * 1000 : retryDelay();
  setState({ nextRetryAt: state.status === 'idle' ? null : new Date(Date.now() + delay).toISOString() });
  timer = setTimeout(tick, delay);
}

export const syncNow = () => tick();

// Called after every local change: sync shortly afterwards if online.
export function scheduleSync() {
  clearTimeout(debounce);
  debounce = setTimeout(tick, 1500);
}

// Makes failed changes pending again (e.g. after an administrator has fixed
// the problem that caused the server to reject them).
export async function retryFailed() {
  await db.sync_records.where('sync_status').equals('failed').modify({ sync_status: 'pending', error: null });
  return syncNow();
}

let started = false;
export async function startAutoSync() {
  if (started) return;
  started = true;
  await loadStoredSettings();
  setState({ lastSyncAt: await getMeta('lastSyncAt') });
  window.addEventListener('online', () => tick());
  window.addEventListener('offline', () => setState({ status: 'offline' }));
  document.addEventListener('visibilitychange', () => { if (!document.hidden) tick(); });
  // Re-evaluate due dates hourly so statuses change at midnight even offline.
  setInterval(refreshIfNewDay, 60 * 60 * 1000);
  await refreshIfNewDay();
  tick();
}
